'use strict';
// One schedule mapping shared by Prototype and Execution. Labels never record actual completion.
function packageSchedule(t){const p=B.prototypeWeek.people.find(p=>p.name===t.owner);return {ready:p.readiness.ids.includes(t.id),first:p.first.ids.includes(t.id),second:p.second.ids.includes(t.id)};}
function scheduleTags(t){const s=packageSchedule(t);return `<span class="schedule-tags">${s.ready?'<span class="schedule-tag ready">Expected ready · verify draft</span>':''}${s.first?'<span class="schedule-tag first">1 Nov · prototype part</span>':''}${s.second?'<span class="schedule-tag second">5 Nov · prototype part</span>':''}${!s.ready&&!s.first&&!s.second?'<span class="schedule-tag later">Later / optional this week</span>':''}</span>`;}
function namedTasks(ids){return `<div class="named-tasks">${ids.map(id=>`<a href="#work/${id}"><b>${id}</b><span>${esc(tasks[id].title)}</span>${scheduleTags(tasks[id])}</a>`).join('')}</div>`;}
function ownerChooser(destination='delivery'){return `<div class="name-picker">${B.prototypeWeek.people.map(p=>`<a class="card" href="${destination==='work'?'#work/owner-':'#delivery/week-'}${p.name}"><span class="avatar">${p.name[0]}</span><strong>${p.name}</strong><small>${destination==='work'?'My tasks and dates':'My two deliveries'} →</small></a>`).join('')}</div>`;}
function simpleStart(){return heading('AEGISLOOP / PROJECT OVERVIEW','From vulnerability evidence to verified remediation.','AegisLoop brings authorized asset collection, applicability assessment, prioritization and remediation into one evidence-backed workflow.')+`<div class="overview-context"><span class="label">CURRENT IMPLEMENTATION SLICE</span><h2>One Ubuntu lab machine. One connected, source-backed result.</h2><p>Build working components by <b>1 November</b>, then connect and test them by <b>5 November</b>. Hams also demonstrates retrieval from saved source documents. The full AI and remediation capabilities remain in the longer plan.</p><div class="actions"><a class="button teal" href="#workflow">Open dynamic workflow →</a><a class="button soft" href="#outputs">Expected outputs & handoffs →</a><a class="button soft" href="#delivery/week">Prototype deliveries →</a><a class="button soft" href="#work/all">Browse all execution tasks →</a></div></div><div class="section-head"><h2>How the product fits together</h2><a href="#system">Explore the system map →</a></div><div class="executive-flow">${[['Collect evidence','Authorized inventory + trusted sources'],['Assess applicability','Affected / not affected / unknown'],['Prioritize','Security policy + evaluated AI'],['Review & remediate','Analyst approval + controlled execution'],['Verify','Fresh evidence + service health']].map((x,i)=>`<a class="flow-step" href="#study/case-${[1,3,4,6,8][i]}"><b>0${i+1}</b><strong>${x[0]}</strong><small>${x[1]}</small></a>`).join('')}</div><div class="section-head"><h2>Team workspaces</h2><a href="#team">Responsibilities and handoffs →</a></div><p class="tagline">Open all of a person’s owned and supporting tasks. Each task carries its prototype delivery labels.</p>${ownerChooser('work')}<div class="grid two"><article class="card"><h3>Delivery labels</h3>${scheduleLegend()}<p>These are planned expectations. They do not confirm that someone finished a task.</p></article><article class="card"><h3>Project knowledge</h3><p>Read the scope before changing the plan. Use the references for research, decisions and open questions.</p><p><a href="#revision/baseline">Current scope baseline →</a></p><p><a href="#open">Questions still to resolve →</a></p><p><a href="#reference">Research, decisions, tests and risks →</a></p><p class="tagline">Exam pause: 7–12 November. The final prototype review date is not yet confirmed.</p></article></div>`;}
function scheduleLegend(){return `<div class="schedule-legend"><p><span class="schedule-tag ready">Expected ready · verify draft</span> The minimum input was expected before implementation. Verify the draft; this is not a Done status.</p><p><span class="schedule-tag first">1 Nov · prototype part</span> Work needed for Sunday’s delivery.</p><p><span class="schedule-tag second">5 Nov · prototype part</span> Work needed for Thursday’s delivery.</p><p><span class="schedule-tag later">Later / optional this week</span> No required delivery this week.</p></div>`;}
function simpleStep(x,i){return `<article class="action-step"><span class="step-number">${i+1}</span><div><h3>${esc(x.do)}</h3><p class="step-example"><b>Example:</b> ${esc(x.example.replace(/^Example:\s*/,''))}</p><p><b>Show that it works:</b> ${esc(x.check)}</p><details><summary>Related tasks and delivery labels</summary>${namedTasks(x.ids)}</details></div></article>`;}
function prototypeWeekView(sub='week'){
 const W=B.prototypeWeek,parts=sub.split('-'),p=W.people.find(p=>p.name===parts[1]),second=parts[2]==='5';
 const head=heading('THIS WEEK / 29 OCT → 5 NOV',p?`${p.name}, here is what you need to do.`:'Two deliveries, with clear work for everyone.','Sunday 1 November: working parts. Thursday 5 November: connect the parts. No delivery deadlines during exams, 7–12 November.')+sectionChangeTag('prototypeWeek')+`<nav class="toc week-tabs" aria-label="Prototype week owners"><a href="#delivery/week" class="${p?'':'selected'}">Week overview</a>${W.people.map(x=>`<a href="#delivery/week-${x.name}" class="${p?.name===x.name?'selected':''}">${x.name}</a>`).join('')}</nav>`;
 if(!p)return head+`<article class="card week-goal"><h2>Thursday’s result</h2><p>Shams collects one real lab machine. Amr supplies the vendor evidence. Mahrous checks whether the machine is affected. Omar displays that same result. Hams demonstrates a source-search program and supplies the screen design.</p><p>This is the first connected prototype build. It does not complete every linked package or the full AI/patch-management product.</p></article>${ownerChooser()}<div class="week-owner-grid">${W.people.map(x=>`<a class="card week-owner" href="#delivery/week-${x.name}"><h2>${x.name}</h2><p>${esc(x.simple.outcome)}</p><span class="schedule-tag first">1 Nov · working component</span> <span class="schedule-tag second">5 Nov · tested handoff</span><p>Open the exact steps, example and proof →</p></a>`).join('')}</div><details class="decision"><summary><h3>How to read task IDs and colored labels</h3></summary><div class="body">${idExplanation()}${scheduleLegend()}</div></details><details class="decision"><summary><h3>Who needs something from whom?</h3></summary><div class="body">${W.handoffs.map(h=>`<p><b>${h.date} · ${h.fromOwner} → ${h.to.join(', ')}</b><br>${esc(h.artifact)}</p>`).join('')}</div></details><details class="decision"><summary><h3>Dates, capacity and what happens if we slip</h3></summary><div class="body">${table(['When','Purpose'],W.rhythm.map(x=>[x[0],x[1]+'. '+x[2]]))}<p>${esc(W.capacity)}</p>${list(W.scopeCuts)}</div></details><details class="decision"><summary><h3>Thursday acceptance and all-package coverage</h3></summary><div class="body">${list(W.acceptance)}<p>Use the Execution date filter to find the same task labels.</p><a href="#work">Open execution →</a></div></details><a class="button soft" download href="prototype-week-plan.md">Download the full week plan</a>`;
 const S=p.simple,x=second?p.second:p.first,steps=second?S.second:S.first;
 return head+`<article class="card simple-objective"><span class="label">YOUR OBJECTIVE</span><h2>${esc(S.outcome)}</h2><p dir="rtl" class="arabic-note">${esc(S.arabic)}</p></article><details class="decision"><summary><h3>Should already be ready before you start — check these inputs</h3></summary><div class="body">${list(S.before)}${namedTasks(p.readiness.ids)}<p>This means the minimum draft/input should exist. It does not mean these entire packages are complete. If missing, prepare that input first.</p></div></details><nav class="toc week-tabs delivery-tabs" aria-label="Choose delivery"><a href="#delivery/week-${p.name}-1" class="${second?'':'selected'}">SUN 1 NOV · First delivery</a><a href="#delivery/week-${p.name}-5" class="${second?'selected':''}">THU 5 NOV · Second delivery</a><a href="#work/week-${p.name}-${second?'5':'1'}">Same tasks in Execution →</a></nav><h2>${second?'For Thursday 5 November':'For Sunday 1 November'}: follow these steps</h2><div class="simple-steps">${steps.map(simpleStep).join('')}</div><details class="decision" open><summary><h3>Which tasks belong to this delivery?</h3></summary><div class="body">${namedTasks(x.ids)}${scheduleLegend()}</div></details><div class="grid two"><article class="card"><h3>Help you give other people</h3>${list(p.support)}</article><article class="card early-flags"><h3>Watch out for these problems</h3>${list(S.warnings)}<p>If one happens, record what is missing and use the relevant guide’s fallback. Do not invent a successful result.</p></article></div><details class="decision"><summary><h3>Files to hand over and technical details</h3></summary><div class="body"><h4>Files or documented equivalents</h4>${list(x.outputs)}<h4>Required input / handoff</h4>${list(x.needs)}<h4>Technical build reference</h4>${list(x.build,true)}<h4>Checkpoint tests</h4>${list(x.proof)}<h4>Optional only after this works</h4>${list(p.stretch)}<p>${esc(p.limit)}</p><p>These are prototype parts. Full package acceptance criteria still apply before declaring a complete package Done.</p></div></details><a class="button soft" href="#delivery/week-${p.name}${second?'-1':'-5'}">${second?'Back to Sunday’s work':'Then see Thursday’s work'} →</a>`;
}
function idExplanation(){return `<p><b>The ID is a reference, not an instruction.</b> A06 means one AI task; its title tells you what to build.</p>${table(['Prefix','Meaning'],[['D','Vulnerability data and matching'],['C','Asset collection, assessment integration and patch workflow'],['A','AI research, code and evaluation'],['P','Platform / backend / API'],['UX','User research and screen design'],['G0–G4','Large project stages — these are not individual tasks']])}`;}
function simpleTaskGuide(t){const p=B.prototypeWeek.people.find(p=>p.name===t.owner),S=p.simple,rows=[...S.first,...S.second].filter(x=>x.ids.includes(t.id));return `<section class="simple-task-intro"><h3>What do I need to do here?</h3>${scheduleTags(t)}${rows.length?rows.map((x,i)=>simpleStep(x,i)).join(''):`<p>${esc(t.goal)}</p><p>This package has no required 1 or 5 November delivery for its owner. Open the full guide for its research, build, tests and outputs.</p>`}<div class="actions"><a href="#delivery/week-${t.owner}">${t.owner}’s delivery instructions →</a></div>${rows.length?`<details class="decision"><summary><h3>Prototype early warnings</h3></summary><div class="body">${list(S.warnings)}</div></details>`:''}</section>`;}
function prototypeWeekPackageLink(t){return `<p class="tagline">The same dated labels are used in This week and Execution. The labels describe expected work, not actual completion.</p>`;}
function reference(){return heading('OPTIONAL / PROJECT REFERENCE','Look up one question. Then return to your work.','Daily instructions are in This week and Execution. These references preserve the full research, architecture and long-term plan.')+`<div class="grid two">${[['Understand the system',[['#system','System map'],['#study/start','Learning guide'],['#team','Full team responsibilities']]],['Scope and decisions',[['#revision','Scope and roadmap'],['#open','Open questions'],['#decisions','Technical decision log']]],['Tests and risks',[['#validation','Full evaluation plan'],['#risks','Full risk register'],['#work','Tests and risks inside each package']]],['Evidence and history',[['#evidence','Research and sources'],['#revision/changes','Plan change history'],['#delivery','Yearlong dependencies and gates']]]].map(([label,links])=>`<article class="card"><h2>${label}</h2>${links.map(([href,text])=>`<p><a href="${href}">${text} →</a></p>`).join('')}</article>`).join('')}</div>`;}
function sidebarNavigation(view,sub){const active=view==='delivery'&&sub.startsWith('week')?'week':['overview','work','team','system','revision','workflow','outputs'].includes(view)?view:'reference';const links=[['overview','#overview','Project overview','The product and current scope'],['week','#delivery/week','Prototype deliveries','1 & 5 November'],['work','#work/all','Execution','All tasks, search and filters'],['workflow','#workflow','Workflow','Inputs, tasks and handoffs'],['outputs','#outputs','Task outputs','Expected results and input owners'],['team','#team','Team responsibilities','Owned work and support'],['system','#system','System map','Components and data flow'],['revision','#revision','Scope & roadmap','Boundaries and implementation order'],['reference','#reference','Project references','Research, decisions, tests and risks']];return links.map(([id,href,label,desc],i)=>`${i===6?'<span class="nav-divider">PROJECT KNOWLEDGE</span>':''}<a href="${href}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}><span class="num">0${i+1}</span><span><b>${label}</b><small>${desc}</small></span></a>`).join('');}

function executionScope(){const label={week:'Prototype week',ready:'Expected starting inputs',first:'1 November delivery',second:'5 November delivery',later:'Later / optional this week'}[filter.weekStage];return `<div><strong>${esc(filter.owner||'All team')}${label?' · '+label:' · All tasks'}</strong><span>${label?'Delivery-focused view. Other tasks remain in the complete plan.':'Complete task scope. Date labels show which parts belong to the prototype.'}</span></div>${label?`<a class="button soft" href="${filter.owner?'#work/owner-'+filter.owner:'#work/all'}">${filter.owner?'All '+esc(filter.owner)+' tasks':'Show all tasks'} →</a>`:''}`;}

function routeDetailLabel(view,sub){if(view==='work'){if(sub==='all')return 'All tasks';if(sub.startsWith('owner-'))return sub.slice(6)+' · All tasks';const m=sub.match(/^week-(\w+)(?:-([15]))?$/);if(m)return m[1]+' · '+(m[2]?m[2]+' November delivery':'Prototype week');}return tasks[sub]?sub:B.decisions.find(d=>d.id===sub)?sub:C[sub]?.label||sub;}
